<?= view('partials/header', ['title' => $title]) ?>
<section class="page-heading rise-in"><div><p class="eyebrow">TRANSACTION LOG</p><h1>Sales history</h1><p>Every recorded sale with its product, customer, staff member, and saved price.</p></div><a class="button" href="<?= site_url('sales/new') ?>">Record sale <span aria-hidden="true">↗</span></a></section>
